/**
 * Measures the selector against reality. For every fixture query and store configuration it previews the decision, then
 * forces each admitted strategy in turn and measures warmed median wall time. The output TSV lists, per decision, every
 * strategy's measured time, the selector's choice and the measured fastest, and every admitted candidate's priced
 * feature vector, so that (1) the regret of each choice is a number, not an argument, and (2) the static prior's
 * coefficients can be fitted from measurements with {@code scripts/lmdb-fit-prior.py}.
 *
 * Enabled with {@code -Drdf4j.lmdb.regret.enabled=true}. Knobs: {@code rdf4j.lmdb.regret.people} (default 3000),
 * {@code rdf4j.lmdb.regret.measurements} (default 7), {@code rdf4j.lmdb.regret.output} (default
 * {@code target/strategy-regret.tsv}).
 */
@Isolated
@EnabledIfSystemProperty(named = "rdf4j.lmdb.regret.enabled", matches = "true")
class LmdbNativeStrategyRegretHarnessTest {

	private static final int PEOPLE = Integer.getInteger("rdf4j.lmdb.regret.people", 3000);
	private static final int MEASUREMENTS = Integer.getInteger("rdf4j.lmdb.regret.measurements", 7);
	private static final int WARMUPS = 2;
	private static final long SEED = 12345L;

	/** Index sets to measure; default the fixture's three. */
	private static final List<String> INDEX_SETS = List.of(System
			.getProperty("rdf4j.lmdb.regret.indexes", String.join(";", LmdbNativeGoldenDecisionsTest.INDEX_SETS))
			.split(";"));
	/** Adjacency modes to measure: {@code lmdbOnly}, {@code adjacency} or both (default). */
	private static final Set<String> ADJACENCY_MODES = Set
			.of(System.getProperty("rdf4j.lmdb.regret.adjacency", "lmdbOnly,adjacency").split(","));

	@Test
	@Timeout(value = 12, unit = TimeUnit.HOURS)
	void measureEveryAdmittedStrategy() throws Exception {
		Map<String, String> previous = new LinkedHashMap<>();
		LmdbNativeGoldenDecisionsTest.STATIC_DECISION_PROPERTIES.forEach((key, value) -> {
			previous.put(key, System.getProperty(key));
			System.setProperty(key, value);
		});
		Path output = Paths.get(System.getProperty("rdf4j.lmdb.regret.output", "target/strategy-regret.tsv"));
		Files.createDirectories(output.toAbsolutePath().getParent());
		List<Timing> timings = new ArrayList<>();
		try {
			for (String indexes : INDEX_SETS) {
				if (ADJACENCY_MODES.contains("lmdbOnly")) {
					timings.addAll(measureConfiguration(indexes, false));
					Files.write(output, LmdbNativeRegretHarness.render(timings), StandardCharsets.UTF_8);
				}
				if (ADJACENCY_MODES.contains("adjacency")
						&& LmdbNativeGoldenDecisionsTest.ADJACENCY_INDEX_SETS.contains(indexes)) {
					timings.addAll(measureConfiguration(indexes, true));
					Files.write(output, LmdbNativeRegretHarness.render(timings), StandardCharsets.UTF_8);
				}
			}
		} finally {
			previous.forEach((key, value) -> {
				if (value == null) {
					System.clearProperty(key);
				} else {
					System.setProperty(key, value);
				}
			});
		}
		Files.write(output, LmdbNativeRegretHarness.render(timings), StandardCharsets.UTF_8);
		System.out.println(LmdbNativeRegretHarness.summary(timings));
		assertThat(timings).isNotEmpty();
	}

	private List<Timing> measureConfiguration(String indexes, boolean adjacency) throws Exception {
		Path dataDir = Files.createTempDirectory("rdf4j-lmdb-regret");
		LmdbStoreConfig config = new LmdbStoreConfig(indexes)
				.setForceSync(false)
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(adjacency)
				.setDirectAdjacencyMode(adjacency ? DirectAdjacencyMode.PREFER : DirectAdjacencyMode.DISABLED);
		if (adjacency) {
			config.setDirectAdjacencyMaxBytes(1L << 30);
		}
		LmdbStore store = new LmdbStore(dataDir.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		List<Timing> timings = new ArrayList<>();
		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				new FoafCliqueDataGenerator(PEOPLE, 30, 3, 5, PEOPLE * 3, SEED).populate(connection);
			}
			if (adjacency) {
				assertThat(AdjacencyEngagementTestAccess.buildNow(store)).isTrue();
			}
			String adjacencyLabel = adjacency ? "adjacency" : "lmdbOnly";
			for (QueryScenario scenario : FoafCliqueQueryCatalog.allScenarios()) {
				timings.addAll(measureQuery(repository, scenario.benchmarkMethodName(), indexes, adjacencyLabel,
						scenario.query()));
			}
			for (Map.Entry<String, String> shape : LmdbNativeGoldenDecisionsTest.SHAPE_QUERIES.entrySet()) {
				timings.addAll(measureQuery(repository, shape.getKey(), indexes, adjacencyLabel, shape.getValue()));
			}
		} finally {
			repository.shutDown();
			FileUtils.deleteDirectory(dataDir.toFile());
		}
		return timings;
	}

	private List<Timing> measureQuery(SailRepository repository, String queryId, String indexes, String adjacency,
			String query) throws Exception {
		return LmdbNativeRegretHarness.measureQuery(repository, queryId, indexes, adjacency, query, WARMUPS,
				MEASUREMENTS);
	}
}
